    row1=[c for c in range(Cn) if I[1][c]!=0]
    runs=[]; s=row1[0]; p=row1[0]
    for c in row1[1:]:
        if c==p+1: p=c
        else: runs.append((s,p)); s=c; p=c
    runs.append((s,p))
    c1=runs[0][0]
    colv=[r for r in range(R) if I[r][c1]!=0]
