    for r in colv[1:]:
        if r==p+1: p=r
        else: rruns.append((s,p)); s=r; p=r
    rruns.append((s,p))
    bs=runs[0][1]-runs[0][0]+1
    frame=I[rruns[0][0]][runs[0][0]]
    G=[[None]*len(runs) for _ in rruns]
    inter={}
    for j,rr in enumerate(rruns):
        for i,cc in enumerate(runs):
            cells=[(r,c) for r in range(rr[0]+1,min(rr[1]+1,rr[0]+bs-1)) for c in range(cc[0]+1,min(cc[1]+1,cc[0]+bs-1))]
            inter[(j,i)]=cells
