        cc=runs[i]
        for c in range(cc[0]+1,min(cc[1]+1,cc[0]+bs-1)):
            for r in range(rruns[k][1]+1, rruns[k+1][0]):
                if I[r][c]==0: O[r][c]=color
    for j in range(len(rruns)):
        for col in set(v for i,v in enumerate(G[j]) if v not in (None,bg,frame)):
            idx=[i for i,v in enumerate(G[j]) if v==col]
            for p,q in zip(idx,idx[1:]):
                for k in range(p,q): hfill(j,k,col)
    for i in range(len(runs)):
        colvals=[G[j][i] for j in range(len(rruns))]
        for col in set(v for j,v in enumerate(colvals) if v not in (None,bg,frame)):
            idx=[j for j,v in enumerate(colvals) if v==col]
            for p,q in zip(idx,idx[1:]):
